'use strict';

// MODULES //

var join = require( 'path' ).join;
var extract = require( './../lib' );


// VARIABLES //

var FIXTURES_DIR = join( __dirname, '..', 'test', 'fixtures' );


// MAIN //

// Extract example blocks from a C source file:
var srcFile = join( FIXTURES_DIR, 'src', 'test_edge_cases.c' );
var srcBlocks = extract( srcFile, 'src' );

console.log( 'Source file — extracted blocks: %d', srcBlocks.length );
console.dir( srcBlocks, {
	'depth': null
});

// Extract example blocks from a Markdown README:
var mdFile = join( FIXTURES_DIR, '..', '..', '..', '..', '..', '..', 'math', 'base', 'special', 'abs', 'README.md' );
var mdBlocks = extract( mdFile, 'markdown' );

console.log( 'Markdown file — extracted blocks: %d', mdBlocks.length );
console.dir( mdBlocks, {
	'depth': null
});
